    fetch(`https://${resource}/${name}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json; charset=UTF-8' },
        body: JSON.stringify(data),
    }).catch(() => {});
}

function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function open({ title, current, floors }) {
    titleEl.textContent = title;
    floorsEl.innerHTML = '';
    // floors arrive highest first; number them bottom-up like a real panel
    floors.forEach((f, i) => {
        const btn = document.createElement('button');
        const isCurrent = f.id === current;
        btn.className = 'floor' + (isCurrent ? ' current' : '') + (f.locked ? ' locked' : '');
        btn.disabled = isCurrent || f.locked;
        const tag = isCurrent ? 'Buradasın' : f.locked ? '<i class="fa-solid fa-lock"></i>' : '';
        btn.innerHTML = `<span class="dot">${floors.length - 1 - i}</span><span class="name">${escapeHtml(f.label)}</span><span class="tag">${tag}</span>`;
        btn.addEventListener('click', () => post('select', { id: f.id }));
        floorsEl.appendChild(btn);
    });
    panel.classList.remove('hidden');
}

window.addEventListener('message', (e) => {
    const d = e.data || {};
    if (d.action === 'open') open(d);
    else if (d.action === 'close') panel.classList.add('hidden');
});

document.getElementById('close').addEventListener('click', () => post('close'));
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' || e.key === 'Backspace') post('close');
});

